import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CoreFunction.functionRound
 */
public class CoreFunction_functionRound_TriageGen1Test {

    private CoreFunction coreFunction;
    private EvalContext mockContext;
    private Expression mockArg1;

    @Before
    public void setUp() {
        mockContext = mock(EvalContext.class);
        mockArg1 = mock(Expression.class);
        // Using a dummy function code and empty expression array for constructor
        coreFunction = new CoreFunction(1, new Expression[0]) {
            // We override to provide the mock argument since getArg1() is used in the method
            @Override
            public Expression getArg1() {
                return mockArg1;
            }

            // Mocking assertArgCount to avoid actual implementation dependency
            @Override
            protected void assertArgCount(int expected) {
                if (getArgumentCount() != expected) {
                    throw new RuntimeException("Argument count mismatch");
                }
            }

            @Override
            public int getArgumentCount() {
                return 1;
            }
        };
    }

    /**
     * Tests rounding a positive number with a fractional part.
     */
    @Test
    public void testFunctionRound_PositiveDecimal() {
        when(mockArg1.computeValue(mockContext)).thenReturn(2.5);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(3.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding a positive number with a fractional part (round down).
     */
    @Test
    public void testFunctionRound_PositiveDecimalDown() {
        when(mockArg1.computeValue(mockContext)).thenReturn(2.4);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(2.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding a negative number.
     */
    @Test
    public void testFunctionRound_Negative() {
        // Math.round(-2.5) results in -2
        when(mockArg1.computeValue(mockContext)).thenReturn(-2.5);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(-2.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding a whole number.
     */
    @Test
    public void testFunctionRound_WholeNumber() {
        when(mockArg1.computeValue(mockContext)).thenReturn(5.0);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(5.0, (Double) result, 0.0);
    }

    /**
     * Tests rounding zero.
     */
    @Test
    public void testFunctionRound_Zero() {
        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        Object result = invokeFunctionRound(mockContext);

        assertEquals(0.0, (Double) result, 0.0);
    }

    /**
     * Helper to access protected method via reflection or subclassing if needed.
     * Since we subclassed in setUp, we can call it directly.
     */
    private Object invokeFunctionRound(EvalContext context) {
        try {
            java.lang.reflect.Method method = CoreFunction.class.getDeclaredMethod("functionRound", EvalContext.class);
            method.setAccessible(true);
            return method.invoke(coreFunction, context);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
